SELECT json_build_object('principals', (SELECT coalesce(json_agg(json_build_array(principal, tier, board, token_hash IS NOT NULL, code_hash IS NOT NULL, code_expires_at, created_at, paired_at, revoked_at, EXTRACT(EPOCH FROM clock_timestamp())::double precision, NULL::double precision, TRUE) ORDER BY principal), '[]'::json) FROM public.principals), 'rejected', '[]'::json);